head.script:
scwin.init = function() {
    widgetContainer.addWidgets([{
            id: "widget1",
            title: "위젯1",
            src: "widgetContainer_Load_WP-3100_(WSQ-2542)_sub.xml",
            scope: true,
            x: 0,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget2",
            title: "위젯2",
            src: "widgetContainer_Load_WP-3100_(WSQ-2542)_sub.xml",
            scope: true,
            x: 1,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget3",
            title: "위젯3",
            src: "widgetContainer_Load_WP-3100_(WSQ-2542)_sub.xml",
            scope: true,
            x: 2,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        }
    ]);
}
scwin.onload = function() {
    output.setValue(output.getValue() + '\n' + 'widgetContainer load complete');
};
scwin.onwidgetload = function(id) {
    output.setValue(output.getValue() + '\n' + '[' + id + '] widget load complete');
};
scwin.checkValue = function() {
    var str = WebSquare.wUnit.getObjById($p.id+'output').getValue().trim();
    st = str.replace(/\r?\n/g, "");
    return st;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일(widgetContainer_Load_WP-3100_(WSQ-2542).xml)을 실행 후 우측의 메시지를 확인한다.
    //1. Run the sample file (widgetContainer_Load_WP-3100_ (WSQ-2542) .xml) and check the message on the right.
    //Verify 1. 위젯1, 위젯2, 위젯3 각각 onwidgetload 이벤트가 발생하고 이후에 위젯컨테이너의 onload 이벤트가 발생되어진다.
    //1. Widget 1, Widget 2, Widget 3 Each onwidgetload event is fired and then the widget container"s onload event is fired.
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue() == '['+$p.id+'widgetContainer_widget1] widget load complete['+$p.id+'widgetContainer_widget2] widget load complete['+$p.id+'widgetContainer_widget3] widget load completewidgetContainer load complete'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 31-Jan-2018
    //End unitTest
    scwin.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
